'use strict';
const updateState={info:null,result:null,checking:false,error:''};
settingTabs.push(['updates','Atualizações','refresh']);
const settingsBeforeUpdates=showSettings;
showSettings=function(tab='general'){if(tab!=='updates')return settingsBeforeUpdates(tab);studio.settings=tab;renderUpdates();loadUpdateInfo()};
async function loadUpdateInfo(){if(updateState.info)return;try{updateState.info=window.amagoDesktop?.updates?await window.amagoDesktop.updates.info():{version:window.amagoVersion,channel:'web'};if(studio.settings==='updates')renderUpdates()}catch{updateState.error='Não foi possível ler a versão instalada.';if(studio.settings==='updates')renderUpdates()}}
function renderUpdates(){
 const desktop=!!window.amagoDesktop?.updates,info=updateState.info,r=updateState.checking?null:updateState.result,labels={available:'Nova versão disponível',current:'Você está na versão mais recente',ahead:'Sua versão é mais recente que a última release',auth:'Acesso ao GitHub necessário',error:'Consulta não concluída'},status=updateState.checking?'Consultando o GitHub…':r?labels[r.status]:'Confira as novidades do Âmago';
 settingsShell('updates',`<div class="eyebrow">ÂMAGO / ATUALIZAÇÕES</div><h3>Mantenha seu espaço atualizado.</h3><div class="update-version"><img src="assets/amago-mark.svg" alt=""><div><strong>Âmago ${esc(info?.version||'…')}</strong><small>${desktop?(info?.channel==='portable'?'Windows · portátil':info?.channel==='development'?'Windows · desenvolvimento':'Windows · instalado'):'Versão web'}</small></div><span>Estável</span></div>${desktop?`<section class="update-status" role="status" aria-live="polite" aria-busy="${updateState.checking}"><strong>${updateState.checking?'<i class="update-spinner" aria-hidden="true"></i>':''}${status}</strong>${r&&!updateState.checking?`<p>${esc(r.message||'Última release: '+r.version)}</p>${r.checkedAt?`<small>Verificado em ${esc(new Date(r.checkedAt).toLocaleString('pt-BR'))}</small>`:''}`:'<p>A consulta busca a última release estável em Nixye/amago.</p>'}</section><div class="settings-button-grid"><button class="solid-button" id="check-update" ${updateState.checking?'disabled':''}>${icon('refresh')}${updateState.checking?'Verificando…':'Verificar atualizações'}</button><button class="plain-button" data-update-open="releases">Abrir releases no GitHub</button></div>${r?.status==='available'?`<div class="update-downloads"><h3>Atualizar para ${esc(r.version)}</h3><div class="settings-button-grid">${r.assets.setup?'<button class="solid-button" data-update-open="setup">Baixar instalador (.exe)</button>':''}${r.assets.portable?'<button class="plain-button" data-update-open="portable">Baixar versão portátil</button>':''}</div><p>${Object.keys(r.assets).length?'O download será aberto no navegador. Depois, feche o Âmago e execute o instalador; se usa a versão portátil, substitua o executável antigo pelo novo.':'Os executáveis ainda não estão disponíveis nessa release. Confira a página no GitHub.'} Sua biblioteca permanece no perfil do Windows.</p></div>`:''}${r?.notes?`<details class="update-notes"><summary>Novidades da versão ${esc(r.version)}</summary><pre>${esc(r.notes)}</pre><button class="plain-button" data-update-open="notes">Ler no GitHub</button></details>`:''}<details class="update-auth" ${r?.status==='auth'?'open':''}><summary>Acesso a repositório privado</summary><p>Para consultar uma release privada, informe um token pessoal do GitHub com acesso a <strong>Nixye/amago</strong> e permissão <strong>Contents: read</strong>. Ele será usado somente nesta consulta e não será salvo.</p><label for="update-token">Token de acesso<input class="field" type="password" id="update-token" autocomplete="off" spellcheck="false" placeholder="Token do GitHub" ${updateState.checking?'disabled':''}></label><small>O download usa a conta conectada ao GitHub no navegador. Você também pode abrir as releases sem informar um token aqui.</small></details><p class="update-footnote">As consultas são manuais. O aplicativo não instala nem reinicia automaticamente.</p>`:`<p>Na web, as novas versões ficam disponíveis ao recarregar a página. Salve seu trabalho e use o botão abaixo para carregar a publicação atual.</p><div class="settings-button-grid"><button class="solid-button" id="reload-version">Salvar e recarregar</button><a class="plain-button" href="https://github.com/Nixye/amago/releases/latest" target="_blank" rel="noopener noreferrer">Versões para Windows</a></div>`}<p class="update-error" role="alert">${esc(updateState.error)}</p>`);
 $('#check-update')?.addEventListener('click',checkAppUpdate);
 $('#reload-version')?.addEventListener('click',async()=>{try{await window.amagoFlush?.();location.reload()}catch{updateState.error='Não foi possível salvar. Resolva o conflito ou exporte o rascunho antes de recarregar.';renderUpdates()}});
 document.querySelectorAll('[data-update-open]').forEach(button=>button.addEventListener('click',async()=>{try{const result=await window.amagoDesktop.updates.open(button.dataset.updateOpen);if(result.error)throw Error(result.error)}catch(error){updateState.error=error.message;renderUpdates()}}));
}
async function checkAppUpdate(){if(updateState.checking)return;let token=$('#update-token')?.value||'';if($('#update-token'))$('#update-token').value='';updateState.checking=true;updateState.error='';renderUpdates();try{updateState.result=await window.amagoDesktop.updates.check(token)}catch{updateState.result={status:'error',message:'Não foi possível consultar as atualizações. Tente novamente.'}}finally{token='';updateState.checking=false;if(studio.settings==='updates')renderUpdates()}}
